effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec4 src = tex(acScreenNorm);
float l = dot(src.rgb, vec3(0.2126, 0.7152, 0.0722));
float a = clamp((l - black) / max(white - black, 0.001), 0.0, 1.0);
a = mix(a, 1.0 - a, clamp(invert, 0.0, 1.0));
gl_FragColor = vec4(src.rgb, mix(src.a, src.a * a, mixAmt));
}
